            for (var rIdx = 0; rIdx < rights.length; rIdx++) {
              html += '<option value="' + esc(rights[rIdx]) + '"' + (pickedRight === rights[rIdx] ? ' selected' : '') + '>' + esc(rights[rIdx]) + '</option>';
            }
            html += '</select></div>';
